<template><div><div class="eyebrow">YOUR SCHEDULE</div><h1 class="page-title">Bookings & history</h1><p class="text-secondary">Review booked slots and cancel an eligible booking.</p><div v-if="error" class="alert alert-warning">{{error}}</div><div class="card panel-card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Examination</th><th>Date & time</th><th>Examiner</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="b in items" :key="b.id"><td><div class="fw-semibold">{{b.examination_name}}</div><div class="small text-secondary">{{b.course_name}}</div></td><td>{{b.exam_date}}<div class="small text-secondary">{{b.start_time}}–{{b.end_time}}</div></td><td>{{b.examiner_name||'—'}}</td><td><span class="badge text-bg-light">{{b.status}}</span></td><td><button v-if="b.status==='Booked'" class="btn btn-sm btn-outline-danger" @click="cancel(b)">Cancel</button></td></tr><tr v-if="!items.length"><td colspan="5" class="text-center py-5 text-secondary">No booking history yet.</td></tr></tbody></table></div></div><div v-if="message" class="alert alert-info mt-3">{{message}}</div></div></template>
<script>
import {api} from '../services/api'
export default {data:()=>({items:[],error:'',message:''}),async mounted(){this.load()},methods:{async load(){try{this.items=(await api.get('/bookings')).data.items;this.error=''}catch(e){this.error=e.response?.data?.error||'Could not load bookings'}},async cancel(b){if(!confirm('Cancel this booking?'))return;try{await api.post(`/bookings/${b.id}/cancel`);this.message='Booking cancelled';this.load()}catch(e){this.message=e.response?.data?.error||'Cancellation failed'}}}}
</script>
